function texasSheriffLabels() {
  return TEXAS_SHERIFFS.map(function (a) {
    return a.label;
  });
}

function texasSheriffByCounty(county) {
  var key = String(county || "").toLowerCase();
  return (
    TEXAS_SHERIFFS.find(function (a) {
      return a.county.toLowerCase() === key;
    }) || null
  );
}
